<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('deals.view');
$pageTitle=t('pipeline');$pdo=db();$owner=(int)($_GET['owner']??0);$currency=(string)($_GET['currency']??'');$q=trim((string)($_GET['q']??''));
$stages=$pdo->query('SELECT * FROM pipeline_stages WHERE is_active=1 ORDER BY sort_order,id')->fetchAll();$where=["d.status IN ('open','won','lost')"];$params=[];if($owner>0){$where[]='d.owner_user_id=?';$params[]=$owner;}if(in_array($currency,['CLP','USD','BRL'],true)){$where[]='d.currency=?';$params[]=$currency;}if($q!==''){$where[]='(d.title LIKE ? OR c.company_name LIKE ? OR CONCAT(ct.first_name,\' \',ct.last_name) LIKE ?)';$term='%'.$q.'%';array_push($params,$term,$term,$term);}
$sql="SELECT d.*,c.company_name,ct.first_name,ct.last_name,u.name owner_name,u.avatar_path,ps.color,ps.name_es stage_name,ps.name_pt stage_name_pt,ps.name_en stage_name_en FROM deals d JOIN pipeline_stages ps ON ps.id=d.stage_id LEFT JOIN clients c ON c.id=d.client_id LEFT JOIN contacts ct ON ct.id=d.contact_id LEFT JOIN users u ON u.id=d.owner_user_id WHERE ".implode(' AND ',$where)." ORDER BY d.updated_at DESC";$s=$pdo->prepare($sql);$s->execute($params);$deals=$s->fetchAll();$byStage=[];foreach($stages as$stage)$byStage[(int)$stage['id']]=[];foreach($deals as$deal)$byStage[(int)$deal['stage_id']][]=$deal;$users=$pdo->query('SELECT id,name FROM users WHERE is_active=1 ORDER BY name')->fetchAll();
$forecast=['CLP'=>0.0,'USD'=>0.0,'BRL'=>0.0];foreach($deals as$d){if($d['status']==='open')$forecast[$d['currency']]+=(float)$d['amount']*((int)$d['probability']/100);}
require __DIR__.'/includes/header.php';?>
<div class="module-tabs commercial-tabs"><a class="active" href="deals.php"><?=crm_icon('kanban')?> Kanban</a><a href="deal_flow.php"><?=crm_icon('activity')?> Flow</a><?php if(has_permission('reports.view')):?><a href="reports.php"><?=crm_icon('report')?> <?=e(t('reports'))?></a><?php endif;?><?php if(has_permission('forms.view')):?><a href="lead_forms.php"><?=crm_icon('form')?> <?=e(t('lead_forms'))?></a><?php endif;?><?php if(has_permission('mailing.view')):?><a href="mailing.php"><?=crm_icon('mail')?> Emails</a><?php endif;?><?php if(has_permission('assistant.use')):?><a href="assistant.php"><?=crm_icon('assistant')?> IA</a><?php endif;?></div>
<div class="pipeline-toolbar"><div><h2 style="margin:0;font-family:'Exo 2'">Embudo de ventas</h2><span class="table-sub">Arrastra las tarjetas entre etapas para actualizar probabilidad, seguimiento y pronóstico.</span></div><div class="actions"><?php if(has_permission('deals.manage')):?><a class="btn btn-primary" href="deal_form.php">+ CREAR NEGOCIO</a><?php endif;?></div></div>
<section class="panel" style="margin-bottom:16px"><div class="panel-body"><form method="get" class="filters-wide"><label>Buscar<input name="q" value="<?=e($q)?>" placeholder="Negocio, cliente o contacto"></label><label>Responsable<select name="owner"><option value="0">Todos</option><?php foreach($users as$u):?><option value="<?=$u['id']?>" <?=$owner===(int)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></label><label>Moneda<select name="currency"><option value="">Todas</option><?php foreach(['CLP','USD','BRL']as$c):?><option <?=$currency===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select></label><button class="btn btn-secondary">FILTRAR</button></form></div></section>
<div class="pipeline-summary" style="margin-bottom:14px"><?php foreach($forecast as$c=>$value):?><span class="badge badge-blue">Pronóstico <?=$c?>: <?=e(format_money($value,$c))?></span><?php endforeach;?><span class="badge badge-green"><?=count($deals)?> negocios</span></div>
<div class="pipeline-board"><?php foreach($stages as$stage):$stageDeals=$byStage[(int)$stage['id']]??[];$stageTotal=[];foreach($stageDeals as$d)$stageTotal[$d['currency']]=($stageTotal[$d['currency']]??0)+(float)$d['amount'];?><section class="pipeline-column" style="--stage-color:<?=e($stage['color'])?>"><header class="pipeline-column-head"><div><h3><?=e(crm_stage_localized($stage))?></h3><small><?=count($stageDeals)?> negocios</small></div><span class="badge badge-gray"><?=(int)$stage['probability']?>%</span></header><div class="pipeline-dropzone" data-stage-dropzone="<?=$stage['id']?>"><?php foreach($stageDeals as$deal):?><article class="deal-card" data-deal-card="<?=$deal['id']?>" style="--stage-color:<?=e($stage['color'])?>"><div class="deal-card-top"><div><h4><a class="table-title" href="deal_view.php?id=<?=$deal['id']?>"><?=e($deal['title'])?></a></h4><p><?=e($deal['company_name']?:trim($deal['first_name'].' '.$deal['last_name'])?:'Sin cliente')?></p></div><div class="probability-ring" style="--probability:<?=(int)$deal['probability']?>"><span><?=(int)$deal['probability']?>%</span></div></div><strong><?=e(format_money($deal['amount'],$deal['currency']))?></strong><?php if($deal['next_action']):?><div class="deal-next">Próximo: <?=e($deal['next_action'])?><?php if($deal['next_action_at']):?> · <?=e((new DateTimeImmutable($deal['next_action_at']))->format('d/m H:i'))?><?php endif;?></div><?php endif;?><div class="deal-card-meta"><span class="deal-owner"><?=user_avatar_html($deal,'avatar')?> <?=e($deal['owner_name']?:'Sin asignar')?></span><small><?=e($deal['expected_close_date']?format_date($deal['expected_close_date']):'Sin fecha')?></small></div></article><?php endforeach;?></div></section><?php endforeach;?></div>
<?php require __DIR__.'/includes/footer.php';?>
